{"code":"def transform(grid):
    out=[row[:] for row in grid]
    pts=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=0: pts.append((r,c,v))
    # two markers: draw their columns vertically; mirror the left marker around the right marker
    pts.sort(key=lambda x:x[1])
    if len(pts)>=2:
        left=pts[0]; right=pts[1]
        for r in range(len(grid)):
            out[r][left[1]]=left[2]
            out[r][right[1]]=right[2]
            mc=2*right[1]-left[1]
            if 0<=mc<len(grid[0]): out[r][mc]=left[2]
    return out"}

